-- 株ピック記録 — Supabase スキーマ＋シード
-- テーブル作成・RLS・公開 select ポリシー・全ラン／全ピックの投入

create table if not exists public.stock_pick_runs (
  id bigint generated always as identity primary key,
  run_date date not null unique,
  kind text,
  headline text,
  detail text,
  source text,
  created_at timestamptz not null default now()
);

create table if not exists public.stock_picks (
  id bigint generated always as identity primary key,
  run_date date not null references public.stock_pick_runs(run_date),
  ticker text,
  name text,
  brand text,
  market text,
  exchange text,
  currency text,
  price numeric,
  per text,
  pbr text,
  dividend_yield text,
  market_cap text,
  range_high numeric,
  range_low numeric,
  range_position_pct numeric,
  benefit text,
  note text,
  memo text,
  status text not null default 'watching',
  kind text,
  chart_key text,
  created_at timestamptz not null default now()
);

alter table public.stock_pick_runs enable row level security;
alter table public.stock_picks enable row level security;

drop policy if exists "public read" on public.stock_pick_runs;
create policy "public read" on public.stock_pick_runs
  for select to anon, authenticated using (true);

drop policy if exists "public read" on public.stock_picks;
create policy "public read" on public.stock_picks
  for select to anon, authenticated using (true);

