insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-20', 'value', '日本株1銘柄・米国株2銘柄をピック', 'データ基準日は日本 2026-11-20終値／米国 2026-11-19セッション終値。次点はKMB（終値$105.25、レンジ位置22.1%・安値から+13.9%、実績PER 10.64倍・利回り4.87%で2項目クリア、PBR 11.94倍は基準外、時価総額$64.58B）がFCF配当性向161.63%で見送り、WY（終値$19.54、11/17から-5.51%、PBR 1.50倍・利回り4.30%）も配当性向133.74%・TTM FCF -$13Mで見送り。除外は東急（終値1,566円、レンジ位置17.0%）が11/18ピック（1,589円）から-1.4%・2営業日で再掲不可、シャープ（終値487円、レンジ位置0.5%・安値から+1.0%）がバリューは予想PER（約13.8〜15.0倍）のみで不合格、ニデック・日産が価格条件通過も会計問題・無配赤字で除外、WU（終値$6.07、11/17から-5.89%）が時価総額$1.89Bでサイズ基準（$2B以上）未達のため除外、MKC・GIS・BHF・INVHは前回ピック時から5%未満の変動で再掲不可、KHCは安値から+18.5%、HRLは+21.6%、CLXは+32.6%で価格条件外。', 'screening') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-19', 'value', 'ピックなし', 'データ基準日：日本 2026-11-19終値／米国 2026-11-18セッション終値。価格・バリュー条件を通過した銘柄は日米ともあったが、全て重複回避ルール（5営業日以内・前回ピック時から5%未満の変動）で再掲不可。LIXIL（5938）は終値1,669.5円・レンジ位置8.3%・安値から+8.9%でバリューはPBR・利回りの2項目でクリアしたが、11/13ピック（1,700.5円）から-1.8%・4営業日で再掲不可。東急（9005）は終値1,580.5円・レンジ位置19.3%・安値から+8.4%でバリューはPER・PBRの2項目でクリアしたが、11/18ピック（1,589円）から-0.5%・1営業日で再掲不可。EMNは終値$62.36・レンジ位置8.5%・安値から+11.1%でバリュー3項目クリアだが、11/13ピック（$65.61）から-4.95%・4営業日で再掲不可。ニデック（6594）・日産（7201）は価格条件を通過したが会計問題・無配・赤字継続のため除外。INVH・WU・BHF・WYも価格・バリュー条件は通過したが前回ピック時から5%未満の変動で再掲不可。TAPは安値から+15.6%で許容15.5%を僅かに超過、PEPはレンジ位置25.1%で僅かに価格条件外。', 'screening') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-18', 'value', '日本株1銘柄・米国株2銘柄をピック', 'データ基準日：日本 2026-11-18終値／米国 2026-11-17セッション終値。次点はEMN $62.30（11/13 $65.61から-5.05%、3営業日）とWU $6.12（11/17 $6.45から-5.1%、1営業日）で、5%ルールは僅かに満たすが上限3銘柄のため／昨日ピックしたばかりのため見送り。価格条件を通過したが除外したのは、ニデック（約6,321億円の減損・PwC監査意見不表明・元役員への損害賠償請求あり、安値の主因が会計問題）、日産（無配・赤字継続）、NKE・SUI（バリューは利回りのみ）、ARE（TTM最終赤字-$1.43B・配当-45.45%減配）、FMC（2025年2月に大幅減配済み）、FLO（時価総額約$1.4Bでサイズ基準未達）、OI・STLA・WHR（TTM赤字・配当停止等）、LKQ（経営混乱・ガイダンス撤回・CEO解任・証券訴訟調査）、IP（TTM純損失-$3.46B・配当がFCFで賄えていない）、WLK（TTM最終赤字・FCFほぼゼロ）、LEG（Yahoo週足データが1週分のみで判定不能）。価格条件外の主な候補はAGC（レンジ位置21.7%だが安値から+25.0%）、CAG（レンジ位置7.4%だが安値から+17.1%で僅かに価格条件外、かつ2026年7月に配当半減）、PEP（レンジ位置25.3%・安値から+15.0%で僅かに価格条件外）、HRL（安値から+19.1%）、KHC（安値から+19.4%）、CMCSA（安値から+23.6%）、MOS（安値から+22.1%）、ZTS（安値から+21.4%）。5年高値・安値はYahoo chart API週足（ザラバ高値・安値ベース、2021-11-15〜2026-11-18）で算出。', 'screening') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-17', 'value', '米国株3銘柄をピック、日本株はピックなし', 'データ基準日は日本 2026-11-17終値／米国 2026-11-16セッション終値。日本株はピックなし：価格条件を通過したのはLIXIL（終値1,674円、レンジ位置8.5%）のみだが11/13ピック時1,700.5円から-1.6%で重複回避により再掲不可で、東急（終値1,629円、レンジ位置26.9%）、ニデック（約6,321億円の減損・PwC監査意見不表明）、日産（無配・赤字継続）、AGC（レンジ位置20.4%・安値から+23.4%）はいずれも除外。米国株ではIP（TTM純損失-$3.46B、FCF配当性向1,306%）、ARE、OI、FLO、KVUE、STLA、WHR、LKQ、WLKを除外し、EMN $63.49、GIS $35.24、MKC $47.13、INVH $27.10は重複回避で見送り、HRL・KHC・TAPは価格条件外。なおYahoo Financeのquote系APIが認証必須となったためファンダメンタルはstockanalysis.comで確認し、5年高値・安値はYahoo chart API週足で算出した。', 'screening') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-16', 'value', 'ピックなし', 'データ基準日：日本 2026-11-16終値／米国 2026-11-13セッション終値。日本株75銘柄のスクリーニングで価格条件を通過したのは3銘柄のみで、5938 LIXILは終値1,701.0円・レンジ位置10.2%・安値から+11.0%で条件通過したが11/13ピック（1,700.5円）から+0.03%・1営業日で重複回避により再掲不可、6594 ニデックは終値1,707円・レンジ位置3.0%・安値から+10.5%だがPBR 2.58倍・TTM純損失▲5,646億円・配当ほぼ0でバリュー0項目、かつ約6,321億円の減損・PwC監査意見不表明・元役員への損害賠償請求あり、7201 日産は終値269.8円・レンジ位置2.9%だが無配・赤字継続で除外。最も近かった価格条件外は5201 AGC（終値4,864円・レンジ位置22.4%・安値から+25.7%）と9005 東急（終値1,652.5円・レンジ位置30.6%）で、日経平均は59,662.02円（前日比 -1,480.33円・-2.42%）。米国株では候補のPCH ポトラッチデルティックは2026年1月30日にRayonier（RYN）へ合併し2026年2月2日にNasdaq上場廃止済みのためピック不可で、$41.73は2026年1月30日の最終取引価格であり11/13終値ではない。次点ではAREが価格条件通過だがTTM最終赤字▲$1.43B・配当▲45.45%減配で除外、BIDUはTTM赤字・無配で除外、CMCSAはバリュー3/3だが安値から+22.9%、KMBは安値から+18.4%、AMCRは安値から+20.8%、PFEは安値から約38%、VZは安値から約54%、BMYは安値から約59%でいずれも価格条件外、PRGO・SON・SUIはTTM赤字で除外、WGOは時価総額約$0.88Bでサイズ基準未達。', 'screening') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-13', 'value', '日本株1銘柄・米国株2銘柄の計3銘柄をピック', 'データ基準日：日本 2026-11-13終値／米国 2026-11-12セッション終値。配信は3銘柄に絞った（1〜3銘柄の上限のため）。BHF ブライハウス・ファイナンシャルは条件を通過したが見送り：終値$44.10、レンジ位置約20.1%（安値から+14.9%）、実績PER 4.42倍・予想PER 2.19〜2.29倍・PBR 0.51倍・無配・時価総額約$2.5Bで、無配でQ3決算がEPS予想を28.7%下回り、GAAP利益の振れが大きいため4銘柄中の最弱として除外。次点・見送り：LKQは終値$19.71、レンジ位置6.6%、予想PER 9.16倍・PBR 0.79倍・利回り6.09%でバリュー3項目を満たすが、10/23の大幅下方修正・通期ガイダンス撤回・CEOと欧州トップの即時解任・欧州ERP混乱・$111Mの減損と当日-22.5%のため見送り。WYは終値$20.46、レンジ位置8.9%、PBR 1.57倍・利回り4.11%だが配当性向133.7%・TTM FCFマイナスで次点。WLKは終値$62.78、レンジ位置6.1%、PBR 0.93倍・利回り3.40%だがTTM最終赤字-$446M・FCFほぼゼロで除外。重複回避で見送り：WU $6.65（11/09 $6.88から-3.3%）、GIS $33.52（11/10 $34.88から-3.9%）、MKC $46.41（11/10 $47.88から-3.1%）、HRL $21.83（11/10 $22.26から-1.9%）、KHC $24.48（11/11 $24.24から+1.0%）、TAP $39.56（11/12 $39.69から-0.3%）。日本株の除外：9005 東急は終値1,627円でレンジ位置26.6%、7201 日産はレンジ位置2.0%で価格条件を通過したが無配・4〜9月期最終赤字397億円で除外、5201 AGCはレンジ位置25.9%・安値から+29.8%で価格条件外。今回はYahoo Finance週足（約360銘柄）で広範囲スクリーニングを実施し、5年高値・安値はYahoo週足（ザラバ高値・安値ベース）で算出、EMN・LKQ・WY・BHFはFinnhub月足／週足またはstockanalysis.comの履歴でクロスチェック済み。', 'screening') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-12', 'value', '米国株1銘柄をピック', 'データ基準日は日本2026-11-12終値／米国2026-11-11セッション終値。日本株は確認した22銘柄のいずれも価格条件＋バリュー基準を同時に満たさずピックなし。重複回避で見送り：LIXILは終値1,692円（+1.96%）、レンジ位置9.6%（5年高値3,185円〜安値1,533円、安値から+10.4%）だが11/06ピック時1,683.5円から+0.5%で再掲不可。東急は終値1,587円（+3.46%）、レンジ位置20.3%（5年高値2,093.5円〜安値1,458円、安値から+8.8%）だが11/11ピック時1,534円から+3.46%で再掲不可。価格条件外で最も近かったのはマツダ（終値1,136円、レンジ位置33.8%）、JFE（終値1,827.5円、レンジ位置39.1%）、名鉄（終値2,012円、レンジ位置48.7%）でいずれもバリュー3/3ながら価格条件外。JTは終値5,996円（+7.80%反発）、レンジ位置69.3%・安値から+199.8%で価格条件外、かつ11/06・11/09の連続ストップ安（ロシア子会社の一時管理）によるイベント要因・来期減配リスクのため除外。地合いは日経平均60,819.36円（前日比-429.23円、-0.70%）、TOPIX 3,937.33（+0.20%）。', 'screening') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-11', 'value', '日本株・米国株各1銘柄をピック', 'データ基準日：日本 2026-11-11終値／米国 2026-11-10セッション終値。重複回避で見送り：5938 LIXILは価格・バリュー条件を通過（終値1,659.5円、レンジ位置7.7%、PBR約0.72倍・利回り約5.43%）したが11/06ピック時から-1.4%で再掲不可。TAPは価格・バリュー3項目を満たす（終値$39.98、レンジ位置12.6%、予想PER 8.51倍・利回り4.81%・PBR 0.80倍）が11/04ピックから-4.5%・4営業日で再掲不可。WU・GIS・MKC・HRLも前回ピック時から5%未満の変動で再掲不可。日本株の除外：AGC（5201）はレンジ位置25.6%・安値から+29.4%で価格条件外。NTT・マツダ・日本精工・三菱ケミカルG・住友化学・ジェイテクト・コニカミノルタ・日本製鉄・JFE・名鉄・リコー・ニコン・東レ・武田薬品・クボタはいずれも5年レンジ上位で除外。米国株の除外：CMCSAは安値から+20.8%、CAGは安値から+21.2%かつ2026年7月に配当半減、CPBは安値から+21.5%かつ2026年9月に減配、CLXは安値から+34.7%、PFE・LYB・BMY・VZ・PEP・UPS・TSN・STZ・SJM・ZBH・SWK・ADM・KDP・TGT・BBY・DOW・KMBはいずれも5年レンジ上位またはバリュー基準未達で除外。注：5年高値・安値はFinnhub週足（ザラバ高値・安値ベース）で算出。チャートはYahoo Financeの週足調整後終値（263点）で作成のため、チャート上の5年高値・安値（東急 2,063.5円／1,490円、KHC $44.29／$21.57）はFinnhub値と僅かに異なる。', 'screening') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-10', 'value', '米国株3銘柄をピック', 'データ基準日：日本 2026-11-10終値／米国 2026-11-09セッション終値。日本株は今回ピックなし：5938 LIXILは価格・バリュー条件を通過（終値1,690円、レンジ位置9.5%、PBR約0.74倍・利回り約5.35%）したが11/06ピック時から+0.4%で重複回避ルールにより再掲不可。最も近いAGC（5201）はレンジ位置22.4%だが安値から+25.7%で価格条件外。その他、三菱ケミカルG・住友化学・日本精工・ジェイテクト・マツダ・日本製鉄・JFE・名鉄・NTT・リコー・ニコン・東レ・武田薬品・クボタはいずれも5年レンジ上位で除外。5年高値・安値はFinnhub週足（ザラバ高値・安値ベース、2021-11-15〜2026-11-02）で算出し、3銘柄ともサブエージェント報告値と一致。チャートは同週足終値＋11/09終値を追加して作成。StooqのCSV取得はタイムアウトのため未使用（チャートはFinnhub週足で代替）。', 'screening') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-09', 'value', '米国株1銘柄をピック（日本株はピックなし）', 'データ基準日：日本 2026-11-09終値／米国 2026-11-06セッション終値。日本株はピックなし：16銘柄を確認し、最も近いAGC（5201）はレンジ位置20.0%だが安値から+23.0%で除外、エプソン（6724）・ジェイテクト（6473）はバリュー3項目を満たすがレンジ位置56.9%・80.9%で除外、マツダ（7261）は予想PER 4.1倍・PBR 0.37倍・利回り4.99%だがレンジ位置31.1%・安値から+54.3%で除外（配当性向98.9%にも注意）、JT（2914）は2日連続ストップ安で5,269円（ロシア子会社の一時管理）—イベント要因の安値・来期減配リスクのため除外、その他リコー（7752）76.6%、日本精工（6471）47.4%、武田薬品（4502）92.1%、パナソニックHD（6752）49.8%、ホンダ（7267）92.1%、キヤノン（7751）80.7%、東レ（3402）81.0%、ニコン（7731）36.9%（TTM赤字）、クボタ（6326）55.9%、電通G（4324）54.7%（TTM赤字・無配）、キリンHD（2503）96.0%、ヤマトHD（9064）60.4%でいずれも価格条件外。米国株の除外：CVSはレンジ位置59.5%・PER 23.9倍、MRKは予想PER 16.3倍・利回り2.32%、HUMはレンジ位置66.3%・PER 38.6倍、ELVはレンジ位置51.7%・PER 17.4倍、VTRSはレンジ位置99.6%（5年高値圏）、MOSはレンジ位置8.6%だが安値から+31.6%・予想PER 24.0倍、NTRはレンジ位置37.8%、KDPはレンジ位置71.5%、SWKはレンジ位置44.8%・PER 20.6倍、DGはレンジ位置34.4%・バリュー0項目、GPNはレンジ位置39.1%・TTM赤字、CNCはレンジ位置61.8%・無配、MOHはレンジ位置29.0%・無配・TTM赤字、PRGOはレンジ位置17.1%だが安値から+71.7%・GAAP赤字継続、DINは時価総額$0.44B・純資産マイナス、BLMNは時価総額$0.83B・無配、WENは時価総額$1.55B・安値から+37.2%、SEEはレンジ位置34.7%・バリュー1項目。5年高値・安値はFinnhub週足（ザラバ高値・安値ベース、2021-11-15〜2026-11-02）で算出。', 'screening') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-07', 'yutai', '手動で追加したピック', '', 'manual') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-06', 'value', '日本株1銘柄をピック', 'データ基準日：日本 2026-11-06終値／米国 2026-11-05セッション終値。除外：AGC（5201）はバリュー3指標を満たすが安値から+21.4%で価格条件外。NTT（9432）・あおぞら銀行（8304）・カシオ（6952）・京セラ（6971）、VZ・PPG・TROW・HOG・BIIBも価格条件またはバリュー基準未達で除外。最近5営業日以内のピック（MKC・9005・KHC・GIS・HRL・CMCSA・TAP・CLX）は重複回避ルールにより対象外。', 'history') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-05', 'value', 'ピックなし', 'データ基準日：日本 2026-11-05終値／米国 2026-11-04セッション終値。スクリーニング対象21銘柄のいずれも価格条件＋バリュー基準を同時に満たさず、無理なピックは行わない。日本株では日本精工（6471）・住友化学（4005）・三菱ケミカルG（4188）・AGC（5201）・名鉄（9048）などがバリュー3指標を満たすも5年レンジ位置55.5%・69%・67%・32%・57.6%で価格条件外。米国株ではSTLA・WHR・BAXが安値圏ながら赤字・配当停止等のため除外。', 'history') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-04', 'value', '米国2銘柄をピック（日本株はピックなし）', 'データ基準日：日本 2026-11-04終値／米国 2026-11-03セッション終値。日本株はピックなし：日本郵船（9101）はバリュー3指標を満たすが5年レンジ上位のため除外。コニカミノルタ（4902）・アステラス（4503）・エーザイ（4523）・旭化成（3407）もレンジ上位で除外。米国次点・除外：CAGは価格条件を通過したが2026年7月の配当半減・減損・ガイダンス引き下げのため見送り。TSN・STZ・ZBHは価格条件外。', 'history') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-03', 'value', '米国1銘柄をピック（日本株はピックなし）', 'データ基準日：日本 2026-11-02終値（11/3は文化の日で休場）／米国 2026-11-02セッション終値。日本株はピックなし：日本製鉄（5401）は予想PER 11.8倍・PBR 0.60倍・利回り3.65%とバリュー3指標を満たすが5年レンジ上位のため除外。SUBARU（7270）も同様に価格条件外。JFE（5411）・コニカミノルタ（4902）・マツダ（7261）も価格条件外。米国次点・除外：UPSは安値から+20.8%で価格条件外、CPBは+19.0%かつ減配済みで見送り、PFEは安値から約30%上で価格条件外。', 'history') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-11-02', 'value', '米国2銘柄をピック（日本株はピックなし）', 'データ基準日：日本 2026-11-02終値／米国 2026-10-30セッション終値。日本株はピックなし：マツダ（7261）・コニカミノルタ（4902）はバリュー3指標を満たすが5年安値から20%以上離れており価格条件を満たさず、JR東日本（9020）・ヤクルト（2267）・ヤマトHD（9064）はバリュー条件2項目未満または安値圏外のため除外。CPBは安値から+15.2%で価格条件ぎりぎり外れ、かつ2026年9月に減配済みのため見送り。', 'history') on conflict (run_date) do nothing;
insert into public.stock_pick_runs (run_date, kind, headline, detail, source) values ('2026-10-31', 'value', '3銘柄をピック（米国2・日本1）', 'データ基準日：日本 2026-10-30終値／米国 2026-10-30セッション終値。通過したが次点：GIS（予想PER 11.1・利回り7.12%、PBR 2.46で基準外）、HRL（PBR 1.49・利回り5.50%）、CPB（PBR 1.66・利回り4.67%、減配あり）。除外：日産自動車（7201）は価格条件は通過も赤字・無配でバリュー基準2項目を満たさず、経営再建中のため除外。WBDは価格データ不整合のため除外。', 'history') on conflict (run_date) do nothing;
insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-20', '5938', 'ＬＩＸＩＬ', 'LIXIL（住宅設備）', 'JP', '東証', '円', 1641, '約40倍', '約0.76倍', '約5.48%（年間90円）', '約4,720〜4,890億円', 3185, 1533, 6.5, '', '11/13ピック（1,700.5円）から5営業日経過のため再掲可。バリューはPBR・利回りの2項目でクリア（予想PERは上期赤字のため約40倍と高い）。2027/3期上期は純損益▲45.9億円の赤字だが、通期予想（純利益120億円）と年90円配当は据え置き。配当90円は会社予想EPS 41.75円を大きく上回るため下期の巻き返しが前提。10年以上減配なし。終値・PBR・利回り・時価総額はFinnhub・stockanalysis.comで一致確認。', '', 'watching', 'value', '');
insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-20', 'EMN', 'イーストマン・ケミカル', 'イーストマン（化学品）', 'US', 'NYSE', '$', 61.71, '実績PER 11.36倍・予想PER 9.78倍', '1.12倍', '5.45%（年間$3.36、16年連続増配）', '約$7.05B', 129.48, 56.11, 7.6, '', '11/13ピック（$65.61）から-5.94%・4営業日で再掲可（5%ルール）。バリュー3項目すべてクリア。TTM純利益$625M・FCF $469M、配当性向 61.88%・FCF配当性向 81.91%。終値はFinnhub・stockanalysis.com・stocknear.comで一致確認。', '', 'watching', 'value', '');
insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-20', 'TAP', 'モルソン・クアーズ・ビバレッジ', 'クアーズ（Coors）', 'US', 'NYSE', '$', 39.96, '実績PER 8.50倍・予想PER 9.46倍', '0.72倍', '4.81%（年間$1.92）', '約$7.40B', 70.9, 35.52, 12.5, '', '11/12ピック（$39.69）から5営業日経過のため再掲可。バリュー3項目すべてクリア。TTM純利益$892.8M・FCF $1.17B、配当性向 40.82%・FCF配当性向 30.44%と余裕あり。終値はFinnhub・stockanalysis.com・MarketBeatで一致確認。', '', 'watching', 'value', '');
insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-18', '9005', '東急', '東急線（東急電鉄）', 'JP', '東証', '円', 1589, '予想PER 9.96倍', 'PBR 0.93倍', '配当利回り 2.01%（年間32円）', '時価総額 約9,929億円', 2093.5, 1458, 20.6, '', '11/11ピック（1,534円）から5営業日経過のため再掲可。11/10の上期決算で営業益を下方修正して急落したが、純利益予想900億円は据え置き。バリューはPER・PBRの2項目でクリア（利回りは2.5%未満）。終値・PER・PBR・利回り・時価総額はYahoo!ファイナンス日本で確認。', '', 'watching', 'value', '');
insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-18', 'MKC', 'マコーミック', 'マコーミック（香辛料）', 'US', 'NYSE', '$', 44.73, '実績PER 8.09倍・予想PER 14.47倍', 'PBR 1.72倍', '配当利回り 4.29%（年間$1.92、11/17に四半期配当$0.48→$0.51へ増配発表＝年間$2.04・利回り約4.56%）', '時価総額 約$12.04B', 107.35, 43.25, 2.3, '', '11/10ピック（$47.88）から6営業日経過・-6.6%で再掲可。下落の主因は英競争・市場庁（CMA）がユニリーバ食品事業との$65B統合に競争上の懸念を示し、1週間以内の対応を求めたこと（11/12頃）。香辛料世界最大手、39年連続増配。終値・PER・PBR・利回り・時価総額はstockanalysis.comで確認。実績PERはTTM純利益$1.49Bベースで一時益を含む可能性があり、予想PER 14.47倍を併記。', '', 'watching', 'value', '');
insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-18', 'GIS', 'ゼネラル・ミルズ', 'チェリオス（Cheerios）', 'US', 'NYSE', '$', 34.68, '予想PER 11.21倍', 'PBR 2.49倍', '配当利回り 7.04%（年間$2.44）', '時価総額 約$18.54B', 90.89, 31.18, 5.9, '', '11/10ピック（$34.88）から6営業日経過のため再掲可。バリューは予想PER・利回りの2項目でクリア（PBRは米国基準2.0未満を満たさず）。TTMはのれん・ブランド減損$1.8B等でGAAP最終赤字（-$894.8M）のため実績PERは算出不可、調整後ベースでは黒字・配当維持。FCF $1.55B、FCF配当性向 84.38%。終値・PER・PBR・利回り・時価総額はstockanalysis.comで確認。', '', 'watching', 'value', '');
