insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-17', 'BHF', 'ブライハウス・フィナンシャル', '生命保険・年金', 'US', 'NYSE', '$', 42.88, '実績PER 4.30倍・予想PER 2.13倍', '0.49倍', '無配', '約$2.47B', 66.8, 38.38, 15.8, '', 'バリューはPER・PBRの2項目でクリア（無配のため利回りは対象外）。簿価 $87.13に対し株価 $42.88。TTM純利益$578M・EPS $9.98・ROE 11.91%。11/5のQ3決算はEPSが予想を28.7%下回り、変額年金のヘッジ損益でGAAP利益の振れが大きい。空売り比率 11.73%、Piotroski Fスコア 3、アナリストはHold・目標株価 $57.00。11/13は4候補中最弱として見送ったが、今回は候補が少なく基準を満たすためピック。', '', 'watching', 'value', '');
insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-17', 'WY', 'ウェイヤーハウザー', '木材・森林管理', 'US', 'NYSE', '$', 20.68, '実績PER 32.93倍・予想PER 87.52倍', '1.59倍', '4.06%（年間$0.84）', '約$14.90B', 43.04, 18.26, 9.8, '', 'バリューはPBR・利回りの2項目でクリア（PERは基準外）。配当性向 133.74%・TTM FCF -$13Mで配当持続性に懸念、インタレストカバレッジ 0.84倍、ROIC 1.50%（WACC 8.00%を下回る）。木材市況の低迷で利益は底値圏。11/13は次点だったが、今回は3銘柄目としてピックしリスクを明記。', '', 'watching', 'value', '');
insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-13', '5938', 'ＬＩＸＩＬ', 'LIXIL（住宅設備・建材）', 'JP', '東証', '円', 1700.5, '約40.75倍', '約0.77倍', '約5.29%（年間90円）', '約4,892億円', 3185, 1533, 10.1, '', '11/06ピック時1,683.5円から5営業日経過のため再掲可。バリューはPBR・利回りの2項目でクリア（予想PERは上期赤字のため約40倍と高い）。2027/3期上期は純損益▲45.9億円の赤字だが、通期予想（純利益120億円）と年90円配当は据え置き。配当90円は会社予想EPS 41.75円を大きく上回るため下期の巻き返しが前提。10年以上減配なし。終値・PER・PBR・利回り・時価総額はYahoo!ファイナンス日本で確認し、stockanalysis.comでPBR・利回り・時価総額をクロスチェックし一致。チャートは調整後週足終値ベースのため、調整後安値は1,389円とザラバ安値1,533円より低く見える点に注意。', '', 'watching', 'value', '');
insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-13', 'EMN', 'イーストマン・ケミカル', 'イーストマン（化学品）', 'US', 'NYSE', '$', 65.61, '実績PER 12.08倍・予想PER 10.40倍', '1.20倍', '5.12%（年間$3.36、16年連続増配）', '約$7.5B', 129.48, 56.11, 12.9, '', 'バリュー3項目すべてクリア。TTM純利益$625M・ROE 10.30%・FCF $469M、配当性向 61.9%（FCFベース81.9%）で配当は賄われている。5年高値・安値はFinnhub月足とYahoo週足で一致確認。終値はFinnhub・stockanalysis.comで一致確認。', '', 'watching', 'value', '');
