insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-10', 'HRL', 'ホーメル・フーズ', 'スパム（SPAM）', 'US', 'NYSE', '$', 22.26, '予想PER 14.6倍', '1.56倍', '5.26%（60年連続増配）', '約$12.1B', 55.11, 18.96, 9.1, '', '11/02以来の再掲（5営業日経過）。実績PERは約35倍と高い点に注意。終値はFinnhub・stockanalysis.comで一致確認（MarketBeatは$22.24と僅差）。', '', 'watching', 'value', '');
insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-09', 'WU', 'ウエスタンユニオン', 'ウエスタンユニオン（国際送金）', 'US', 'NYSE', '$', 6.88, '4.96〜6.55倍', '約2.35倍', '13.67%', '約$2.15B', 20.4, 5.87, 7, '', 'バリューはPER・利回りの2項目でクリア（PBRは米国基準2.0未満を満たさず）。安値から+17.2%で「約15%」を僅かに上回る点に注意。配当利回り13.67%（年間$0.94）。11/4のQ3決算はEPS $0.42（予想$0.3381を上回る）で通期見通しを上方修正。売上は長期縮小（$5.6B→$4.05B）、配当性向89.52%（減配リスク）、D/E 3.24倍、アナリストコンセンサスはReduce・目標株価$6.95。時価総額は出所で乖離（Finnhub $1.96B・MarketBeat/Kinfo $2.15B・financialcontent $2.58B、大半は$2B以上）。5年安値$5.87は2026年9月28日週の安値、5年高値$20.40は2022年2月14日週の高値。', '', 'watching', 'value', '');
insert into public.stock_picks (run_date, ticker, name, brand, market, exchange, currency, price, per, pbr, dividend_yield, market_cap, range_high, range_low, range_position_pct, benefit, note, memo, status, kind, chart_key) values ('2026-11-07', '3160', '大光', '業務用スーパー「アミカ」（愛知県地盤）', 'JP', '東証', '円', 572, '', '', '', '', null, null, null, '500株でアミカ商品券2,000円またはQUOカード1,000円の選択制、年2回（アミカ券選択が前提）', '権利確定日2026-11-30、権利付最終日2026-11-26。優待利回り0.70%／回（年約1.40%、アミカ券前提）。QUOカードをアミカ店舗で交換するとアミカ券2倍になる制度あり。最低取得額286,000円。株価は2026-11-06終値。', '', 'watching', 'yutai', '2026-11-07-3160');
